/**
 * ═══════════════════════════════════════════════════════════════════════════════
 *  ERROR BOUNDARY — Sentry-Enhanced Error Handling
 * ═══════════════════════════════════════════════════════════════════════════════
 * Catches React rendering errors and reports them to Sentry with full context.
 * Provides user feedback dialog for error reporting.
 *
 * Uses lazy-loaded Sentry via dynamic import — no static @sentry/react import,
 * keeping the error boundary out of the critical bundle path.
 * ═══════════════════════════════════════════════════════════════════════════════
 */

import { Component, ErrorInfo, ReactNode } from 'react';
import { getSentryAsync } from '../../core/SentryInit';

interface Props {
  children: ReactNode;
  fallback?: ReactNode;
}

interface State {
  hasError: boolean;
  eventId: string | null;
}

class ErrorBoundary extends Component<Props, State> {
  constructor(props: Props) {
    super(props);
    this.state = {
      hasError: false,
      eventId: null,
    };
  }

  static getDerivedStateFromError(_: Error): State {
    return { hasError: true, eventId: null };
  }

  componentDidCatch(error: Error, errorInfo: ErrorInfo) {
    console.error('ErrorBoundary caught an error:', error, errorInfo);

    // Auto-reload on stale chunk errors (happens after new deployments)
    if (
      error.message?.includes('dynamically imported module') ||
      error.message?.includes('Failed to fetch') ||
      error.message?.includes('ChunkLoadError') ||
      error.name === 'ChunkLoadError'
    ) {
      console.warn('[ErrorBoundary] Stale chunk detected, reloading...');
      window.location.reload();
      return;
    }

    // Capture exception with Sentry (lazy-loaded) and get event ID
    getSentryAsync()
      .then((Sentry) => {
        if (!Sentry) return;
        Sentry.withScope((scope) => {
          scope.setContext('react', {
            componentStack: errorInfo.componentStack,
          });

          const eventId = Sentry.captureException(error);
          this.setState({ eventId });
        });
      })
      .catch(() => {
        /* Sentry unavailable */
      });
  }

  handleReportClick = () => {
    if (!this.state.eventId) return;
    const eventId = this.state.eventId;
    getSentryAsync()
      .then((Sentry) => {
        if (!Sentry) return;
        Sentry.showReportDialog({
          eventId,
          title: 'Help us fix this issue',
          subtitle: 'Tell us what happened',
          subtitle2: 'Your feedback helps us improve Club Arena',
        });
      })
      .catch(() => {
        /* Sentry unavailable */
      });
  };

  render() {
    if (this.state.hasError) {
      // Custom fallback UI
      return (
        this.props.fallback || (
          <div
            style={{
              display: 'flex',
              flexDirection: 'column',
              alignItems: 'center',
              justifyContent: 'center',
              minHeight: '100vh',
              padding: '2rem',
              background: 'linear-gradient(135deg, #1a1a2e 0%, #16213e 100%)',
              color: '#fff',
              fontFamily: 'system-ui, -apple-system, sans-serif',
            }}
          >
            <div
              style={{
                maxWidth: '500px',
                textAlign: 'center',
                background: 'rgba(255, 255, 255, 0.05)',
                padding: '3rem',
                borderRadius: '16px',
                border: '1px solid rgba(255, 255, 255, 0.1)',
              }}
            >
              <div
                style={{
                  fontSize: '4rem',
                  marginBottom: '1rem',
                }}
              >
                Warning
              </div>

              <h1
                style={{
                  fontSize: '1.5rem',
                  marginBottom: '1rem',
                  fontWeight: '600',
                }}
              >
                Something went wrong
              </h1>

              <p
                style={{
                  color: 'rgba(255, 255, 255, 0.7)',
                  marginBottom: '2rem',
                  lineHeight: '1.6',
                }}
              >
                We've been notified and are working on a fix. You can help us by providing more
                details about what happened.
              </p>

              <div
                style={{
                  display: 'flex',
                  gap: '1rem',
                  justifyContent: 'center',
                  flexWrap: 'wrap',
                }}
              >
                {this.state.eventId && (
                  <button
                    onClick={this.handleReportClick}
                    style={{
                      padding: '0.75rem 1.5rem',
                      background: 'linear-gradient(135deg, #667eea 0%, #764ba2 100%)',
                      color: '#fff',
                      border: 'none',
                      borderRadius: '8px',
                      fontSize: '1rem',
                      fontWeight: '500',
                      cursor: 'pointer',
                      transition: 'transform 0.2s',
                    }}
                    onMouseOver={(e) => {
                      e.currentTarget.style.transform = 'translateY(-2px)';
                    }}
                    onMouseOut={(e) => {
                      e.currentTarget.style.transform = 'translateY(0)';
                    }}
                  >
                    Report Feedback
                  </button>
                )}

                <button
                  onClick={() => window.location.reload()}
                  style={{
                    padding: '0.75rem 1.5rem',
                    background: 'rgba(255, 255, 255, 0.1)',
                    color: '#fff',
                    border: '1px solid rgba(255, 255, 255, 0.2)',
                    borderRadius: '8px',
                    fontSize: '1rem',
                    fontWeight: '500',
                    cursor: 'pointer',
                    transition: 'all 0.2s',
                  }}
                  onMouseOver={(e) => {
                    e.currentTarget.style.background = 'rgba(255, 255, 255, 0.15)';
                    e.currentTarget.style.transform = 'translateY(-2px)';
                  }}
                  onMouseOut={(e) => {
                    e.currentTarget.style.background = 'rgba(255, 255, 255, 0.1)';
                    e.currentTarget.style.transform = 'translateY(0)';
                  }}
                >
                  Reload Page
                </button>
              </div>

              {this.state.eventId && (
                <p
                  style={{
                    marginTop: '2rem',
                    fontSize: '0.875rem',
                    color: 'rgba(255, 255, 255, 0.5)',
                  }}
                >
                  Error ID: {this.state.eventId}
                </p>
              )}
            </div>
          </div>
        )
      );
    }

    return this.props.children;
  }
}

export default ErrorBoundary;
